{
  "path": "lib/screens/login_screen.dart",
  "content": "import 'package:flutter/material.dart';\nimport 'package:firebase_auth/firebase_auth.dart';\nimport 'package:cloud_firestore/cloud_firestore.dart';\nimport 'package:your_app_name/screens/home_screen.dart'; // عدل المسار حسب اسم المشروع\n\nclass LoginScreen extends StatefulWidget {\n  const LoginScreen({Key? key}) : super(key: key);\n\n  @override\n  State<LoginScreen> createState() => _LoginScreenState();\n}\n\nclass _LoginScreenState extends State<LoginScreen> {\n  final _formKey = GlobalKey<FormState>();\n  final TextEditingController _emailController = TextEditingController();\n  final TextEditingController _passwordController = TextEditingController();\n\n  bool _isLoading = false;\n  String? _errorMessage;\n\n  @override\n  void dispose() {\n    _emailController.dispose();\n    _passwordController.dispose();\n    super.dispose();\n  }\n\n  Future<void> _signIn() async {\n    if (!_formKey.currentState!.validate()) return;\n    setState(() {\n      _isLoading = true;\n      _errorMessage = null;\n    });\n    try {\n      UserCredential userCredential = await FirebaseAuth.instance\n          .signInWithEmailAndPassword(\n              email: _emailController.text.trim(),\n              password: _passwordController.text.trim());\n\n      // يمكن إضافة أي إعدادات إضافية بعد تسجيل الدخول، مثل جلب بيانات المستخدم من Firestore\n      Navigator.of(context).pushReplacement(\n        MaterialPageRoute(builder: (_) => const HomeScreen()),\n      );\n    } on FirebaseAuthException catch (e) {\n      String message;\n      switch (e.code) {\n        case 'user-not-found':\n          message = 'المستخدم غير موجود. يرجى التسجيل أولاً.';\n          break;\n        case 'wrong-password':\n          message = 'كلمة المرور غير صحيحة.';\n          break;\n        case 'invalid-email':\n          message = 'البريد الإلكتروني غير صالح.';\n          break;\n        case 'user-disabled':\n          message = 'تم تعطيل حسابك. تواصل مع الدعم.';\n          break;\n        default:\n          message = 'حدث خطأ غير متوقع. الرجاء المحاولة مرة أخرى.';\n      }\n      setState(() {\n        _errorMessage = message;\n      });\n    } catch (e) {\n      setState(() {\n        _errorMessage = 'فشل الاتصال بالخادم. يرجى التحقق من الإنترنت.';\n      });\n    } finally {\n      if (mounted) {\n        setState(() {\n          _isLoading = false;\n        });\n      }\n    }\n  }\n\n  Future<void> _resetPassword() async {\n    if (_emailController.text.trim().isEmpty) {\n      ScaffoldMessenger.of(context).showSnackBar(\n        const SnackBar(content: Text('يرجى إدخال البريد الإلكتروني أولاً')),\n      );\n      return;\n    }\n    try {\n      await FirebaseAuth.instance\n          .sendPasswordResetEmail(email: _emailController.text.trim());\n      ScaffoldMessenger.of(context).showSnackBar(\n        const SnackBar(content: Text('تم إرسال رابط إعادة تعيين كلمة المرور إلى بريدك الإلكتروني')),\n      );\n    } on FirebaseAuthException catch (e) {\n      ScaffoldMessenger.of(context).showSnackBar(\n        SnackBar(content: Text(e.message ?? 'خطأ في إرسال البريد')),\n      );\n    }\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      backgroundColor: Theme.of(context).scaffoldBackgroundColor,\n      body: Center(\n        child: SingleChildScrollView(\n          padding: const EdgeInsets.symmetric(horizontal: 24.0),\n          child: Form(\n            key: _formKey,\n            child: Column(\n              mainAxisSize: MainAxisSize.min,\n              crossAxisAlignment: CrossAxisAlignment.stretch,\n              children: [\n                const Text(\n                  'مرحباً بكم في تطبيق تصحيح الأخطاء',\n                  textAlign: TextAlign.center,\n                  style: TextStyle(\n                    fontSize: 24,\n                    fontWeight: FontWeight.bold,\n                  ),\n                ),\n                const SizedBox(height: 32),\n                TextFormField(\n                  controller: _emailController,\n                  keyboardType: TextInputType.emailAddress,\n                  decoration: const InputDecoration(\n                    labelText: 'البريد الإلكتروني',\n                    border: OutlineInputBorder(),\n                  ),\n                  validator: (value) {\n                    if (value == null || value.isEmpty) {\n                      return 'الرجاء إدخال البريد الإلكتروني';\n                    }\n                    if (!RegExp(r'^[\\w-\\.]+@([\\w-]+\\.)+[\\w-]{2,4}\$')\n                        .hasMatch(value)) {\n                      return 'صيغة البريد غير صحيحة';\n                    }\n                    return null;\n                  },\n                ),\n                const SizedBox(height: 16),\n                TextFormField(\n                  controller: _passwordController,\n                  obscureText: true,\n                  decoration: const InputDecoration(\n                    labelText: 'كلمة المرور',\n                    border: OutlineInputBorder(),\n                  ),\n                  validator: (value) {\n                    if (value == null || value.isEmpty) {\n                      return 'الرجاء إدخال كلمة المرور';\n                    }\n                    if (value.length < 6) {\n                      return 'يجب أن تكون كلمة المرور 6 أحرف على الأقل';\n                    }\n                    return null;\n                  },\n                ),\n                const SizedBox(height: 24),\n                if (_errorMessage != null) ...[\n                  Text(\n                    _errorMessage!,\n                    style: const TextStyle(color: Colors.red),\n                    textAlign: TextAlign.center,\n                  ),\n                  const SizedBox(height: 12),\n                ],\n                ElevatedButton(\n                  onPressed: _isLoading ? null : _signIn,\n                  style: ElevatedButton.styleFrom(\n                    padding: const EdgeInsets.symmetric(vertical: 14),\n                  ),\n                  child: _isLoading\n                      ? const SizedBox(\n                          height: 20,\n                          width: 20,\n                          child: CircularProgressIndicator(\n                            strokeWidth: 2,\n                            color: Colors.white,\n                          ),\n                        )\n                      : const Text('تسجيل الدخول'),\n                ),\n                const SizedBox(height: 12),\n                TextButton(\n                  onPressed: _resetPassword,\n                  child: const Text('نسيت كلمة المرور؟'),\n                ),\n                const Divider(height: 32),\n                TextButton(\n                  onPressed: () {\n                    // انتقل إلى شاشة التسجيل (تحتاج إلى إنشائها)\n                    Navigator.of(context).pushNamed('/register');\n                  },\n                  child: const Text('ليس لديك حساب؟ أنشئ حساباً'),\n                ),\n              ],\n            ),\n          ),\n        ),\n      ),\n    );\n  }\n}\n"
}